insert into public.education_modules (slug, language_code, role_context, title, body, source_note, version) values
('breathing-test-meaning', 'ta', 'patient', 'உங்கள் மூச்சுப் பரிசோதனையின் பொருள்', 'இந்த கருவி FEV1, FVC மற்றும் FEV1/FVC மதிப்புகளை 45-90 வயதுடைய இந்திய பெரியவர்களுக்கான LASI குறிப்புமதிப்புகளுடன் ஒப்பிடுகிறது. முடிவுகள் அறிகுறிகள், பரிசோதனை, பரிசோதனைத் தரம் மற்றும் உள்ளூர் மருத்துவ வழிகாட்டுதலுடன் விளக்கப்பட வேண்டும்.', 'LASI குறிப்புச் சமன்பாடுகள்; உள்ளூர் மருத்துவ மதிப்பாய்வு தேவை.', 'v1'),
('warning-symptoms', 'ta', 'patient', 'எப்போது அவசர சிகிச்சை தேவை', 'கடுமையான மூச்சுத்திணறல், நெஞ்சு வலி, மயக்கம், குழப்பம், நீல உதடு, இரத்தக் காசல், திடீர் பலவீனம் அல்லது வேகமாக மோசமடையும் உடல்நிலை இருந்தால் அவசர உதவி பெறுங்கள்.', 'பாதுகாப்பு கல்வி; அவசர சேவைகளுக்குப் பதிலல்ல.', 'v1'),
('visit-preparation', 'ta', 'patient', 'வருகைக்கு தயாராகுதல்', 'மருந்துப் பட்டியல், பழைய அறிக்கைகள், தடுப்பூசி வரலாறு, அறிகுறி குறிப்புகள், விழுதல் வரலாறு, பராமரிப்பாளர் கவலைகள் மற்றும் கேள்விகளை கொண்டு வாருங்கள்.', 'பகிர்ந்த முடிவெடுப்பிற்கான நோயாளர் கல்வி.', 'v1'),
('breathing-test-meaning', 'te', 'patient', 'మీ శ్వాస పరీక్ష అర్థం', 'ఈ సాధనం FEV1, FVC మరియు FEV1/FVC విలువలను 45-90 సంవత్సరాల భారతీయ పెద్దల LASI సూచిక విలువలతో పోలుస్తుంది. ఫలితాలను లక్షణాలు, పరీక్ష, పరీక్ష నాణ్యత మరియు స్థానిక వైద్య మార్గదర్శకాలతో అర్థం చేసుకోవాలి.', 'LASI సూచిక సమీకరణాలు; స్థానిక వైద్య సమీక్ష అవసరం.', 'v1'),
('warning-symptoms', 'te', 'patient', 'ఎప్పుడు అత్యవసర సహాయం పొందాలి', 'తీవ్ర శ్వాస ఇబ్బంది, ఛాతి నొప్పి, మూర్ఛ, గందరగోళం, నీలి పెదవులు, రక్తంతో దగ్గు, అకస్మాత్తు బలహీనత లేదా వేగంగా దిగజారుతున్న అనారోగ్యం ఉంటే అత్యవసర సహాయం పొందండి.', 'భద్రతా విద్య; అత్యవసర సేవలకు ప్రత్యామ్నాయం కాదు.', 'v1'),
('visit-preparation', 'te', 'patient', 'సందర్శనకు సిద్ధం కావడం', 'మందుల జాబితా, పాత నివేదికలు, టీకా చరిత్ర, లక్షణాల గమనికలు, పడిపోవడం చరిత్ర, సంరక్షకుల ఆందోళనలు మరియు ప్రశ్నలు తీసుకురండి.', 'సహ నిర్ణయం కోసం రోగి విద్య.', 'v1'),
('breathing-test-meaning', 'mr', 'patient', 'आपल्या श्वसन चाचणीचा अर्थ', 'हे साधन FEV1, FVC आणि FEV1/FVC ची तुलना 45-90 वर्षांच्या भारतीय प्रौढांसाठी LASI संदर्भ मूल्यांशी करते. निकाल लक्षणे, तपासणी, चाचणी गुणवत्ता आणि स्थानिक वैद्यकीय मार्गदर्शनासह समजावेत.', 'LASI संदर्भ समीकरणे; स्थानिक वैद्यकीय आढावा आवश्यक.', 'v1'),
('warning-symptoms', 'mr', 'patient', 'तातडीची मदत कधी घ्यावी', 'तीव्र श्वास लागणे, छातीत दुखणे, बेशुद्ध पडणे, गोंधळ, ओठ निळे होणे, रक्ताची खोकला, अचानक अशक्तपणा किंवा वेगाने बिघडणारी तब्येत असल्यास तातडीची मदत घ्या.', 'सुरक्षा शिक्षण; आपत्कालीन सेवांचा पर्याय नाही.', 'v1'),
('visit-preparation', 'mr', 'patient', 'भेटीसाठी तयारी', 'औषधांची यादी, जुने अहवाल, लसीकरण इतिहास, लक्षणांच्या नोंदी, पडण्याचा इतिहास, काळजीवाहूंच्या चिंता आणि प्रश्न सोबत आणा.', 'सामायिक निर्णयासाठी रुग्ण शिक्षण.', 'v1')
